//                          Fsm Action API definition                         //
//----------------------------------------------------------------------------//

import type { EventMap, EventName, PayloadArgs, PayloadOf } from './event-types'
import type { TimerKey, ScheduleParams } from './timer-registry'

type TimerPayloadField<Events extends EventMap, K extends EventName<Events>> =
  [PayloadOf<Events, K>] extends [void]
    ? { payload?: never }
    : { payload: Readonly<PayloadOf<Events, K>> }


export type TimerParams<Events extends EventMap, K extends EventName<Events>> = 
  {
    key?: TimerKey
    event: K
  }
  & Omit<ScheduleParams, 'key'>
  & TimerPayloadField<Events, K>

/**
 * The API exposed to actions via the `fsm` parameter.
 *
 */
export type FsmActionApi<Events extends EventMap> = {
  /** Dispatches an event to the FSM. The event will be processed after the
   * current action finishes. */
  dispatch<K extends EventName<Events>>(event: K, ...args: PayloadArgs<Events, K>): void

  /** Schedules a timer to dispatch an event after a delay. 
   *
   * @param params - parameters object:
   *   - `key` (optional): a unique identifier for the timer. If not provided, the event will be used
   *   - `event`: the event to dispatch when the timer expires
   *   - `payload`: the payload to include with the dispatched event, iff the event has one
   *   - `ms`: delay duration in milliseconds, or `Infinity` for no expiration.
   *   - `deadline`: absolute expiration time, in performance.now() time.
   *
   *   Exactly one of `ms` or `deadline` must be provided.
   *
   * If a timer with the same key already exists, it will be replaced with the new timer.
   */
  timer<K extends EventName<Events>>(params: TimerParams<Events, K>): void

  /** Cancels a previously scheduled timer */
  cancelTimer(key: TimerKey): void

  /** Cancels all previously scheduled timers. Use with caution! */
  cancelAllTimers(): void
}

