//                          DSL definitions                                   //
//----------------------------------------------------------------------------//

import type { EventMap, EventName } from './event-types'
import type { BeginAction, EntryAction, ExitAction, Guard, TransitionAction } from './action-types'

// local type aliases so the doc will show the public names (even though it can't provide links to them)
type FsmBeginAction<State extends string, Events extends EventMap, K extends EventName<Events>, Context>      = BeginAction<State, Events, Context, K>
type FsmEntryAction<State extends string, Events extends EventMap, K extends EventName<Events>, Context>      = EntryAction<State, Events, Context, K>
type FsmExitAction<State extends string, Events extends EventMap, K extends EventName<Events>, Context>       = ExitAction<State, Events, Context, K>
type FsmGuard<State extends string, Events extends EventMap, K extends EventName<Events>, Context>            = Guard<State, Events, Context, K>
type FsmTransitionAction<State extends string, Events extends EventMap, K extends EventName<Events>, Context> = TransitionAction<State, Events, Context, K>


/**
 * Top-level builder passed to {@link FsmEngine.define}.
 *
 * Used to declare the machine's name, initial state, states, and fallback
 * event handling.
 */
export interface FsmBuilder<State extends string, Events extends EventMap, Context> {
  /**
   * Sets a human-readable name for the machine.
   *
   * Used in trace output. If not set, the engine uses its default name.
   */
  name(name: string): void 

  /**
   * Sets the initial state explicitly.
   *
   * If not called, the first declared state becomes the initial state.
   */
  initialState(state: State): void 

  /**
   * Declares a state.
   *
   * The body receives a {@link FsmStateBuilder} for defining entry and exit
   * actions and event handling for the state.
   */
  state(state: State, body?: (b: FsmStateBuilder<State, Events, Context>) => void): void 

  // -----------
  // fallback() overloads that help typescript infer the event and payload types.
  //
  // Hidden from the docs since the main fallback() signature is sufficient

  /** @hidden */
  fallback<K extends EventName<Events>>(event: K, body: (e: FsmEventBuilder<State, Events, Context, K>) => void): void

  /** @hidden */
  fallback<const K extends readonly EventName<Events>[]>(events: K, body: (e: FsmEventBuilder<State, Events, Context, K[number]>) => void): void

  /**
   * Declares fallback handling for one or more events.
   *
   * Fallback rules are considered only when the current state has no matching
   * transition for the event.
   *
   * The body receives an {@link FsmEventBuilder}, the same DSL used by
   * {@link FsmStateBuilder.event | state event handlers}.
   */
  fallback(eventOrEvents: EventName<Events> | readonly EventName<Events>[], body: (e: FsmEventBuilder<State, Events, Context, EventName<Events>>) => void): void 
}

/**
 * Builder used to define a single state.
 *
 * Supports entry and exit actions and event handling for the state.
 */
export interface FsmStateBuilder<State extends string, Events extends EventMap, Context> {
  /**
   * Adds an entry action for this state.
   *
   * Entry actions run when the machine enters the state. Multiple entry actions
   * are allowed and run in declaration order.
   *
   * See {@link FsmEntryAction} for the action function type signature.
   */
  onEnter(action: FsmEntryAction<State, Events, EventName<Events>, Context>): void 

  /**
   * Adds an exit action for this state.
   *
   * Exit actions run when the machine leaves the state. Multiple exit actions
   * are allowed and run in declaration order.
   *
   * See {@link FsmExitAction} for the action function type signature.
   */
  onExit(action: FsmExitAction<State, Events, EventName<Events>, Context>): void 

  // -----------
  // event() overloads that help typescript infer the event and payload types.
  //
  // Hidden from the docs since the main () signature is sufficient

  /** @hidden */
  event<K extends EventName<Events>>(event: K, body: (e: FsmEventBuilder<State, Events, Context, K>) => void): void

  /** @hidden */
  event<const K extends readonly EventName<Events>[]>(events: K, body: (e: FsmEventBuilder<State, Events, Context, K[number]>) => void): void

  /**
   * Declares event handling for one or more events in this state.
   *
   * The body receives an {@link FsmEventBuilder} for declaring begin actions,
   * guards, and transitions.
   */
  event(eventOrEvents: EventName<Events> | readonly EventName<Events>[], body: (e: FsmEventBuilder<State, Events, Context, EventName<Events>>) => void): void 
}

/**
 * Shared transition-declaring surface used by event builders and guarded
 * transition builders.
 *
 * Supports declaring either an external transition to another state or an
 * internal transition that stays in the current state.
 */
export interface FsmTransitionBuilder<State extends string, Events extends EventMap, Context, K extends EventName<Events>> {
  /**
   * Declares an external transition to `target`.
   *
   * The optional body receives a {@link FsmTransitionActionsBuilder} for
   * declaring transition actions.
   *
   * If `target` is the current state, the machine still performs an external
   * transition: exit actions run, then transition actions, then entry actions.
   */
  toState(target: State, body?: (t: FsmTransitionActionsBuilder<State, Events, Context, K>) => void): void 

  /**
   * Declares an internal transition.
   *
   * The machine remains in the current state; state exit and entry actions do
   * not run. The optional body receives a
   * {@link FsmTransitionActionsBuilder} for declaring transition actions.
   */
  stay(body?: (t: FsmTransitionActionsBuilder<State, Events, Context, K>) => void): void
}

/**
 * Builder used to define handling for a particular event within a state or
 * fallback.
 *
 * Supports begin actions, guarded transitions, and unguarded transitions.
 */
export interface FsmEventBuilder<State extends string, Events extends EventMap, Context, K extends EventName<Events>> extends FsmTransitionBuilder<State, Events, Context, K> {
  /**
   * Adds a begin action for this event handler.
   *
   * Begin actions run before any transition for the event is evaluated.
   * Multiple begin actions are allowed and run in declaration order.
   *
   * See {@link FsmBeginAction} for the action function type signature.
   */
  begin(action: FsmBeginAction<State, Events, K, Context>): void

  /**
   * Starts a guarded transition.
   *
   * Returns a {@link FsmGuardedTransitionBuilder} that allows additional guards
   * to be chained before the final transition is declared.
   *
   * See {@link FsmGuard} for the guard function type signature.
   */
  when(cond: FsmGuard<State, Events, K, Context>): FsmGuardedTransitionBuilder<State, Events, Context, K>
}

/**
 * Builder used after one or more guards have been declared.
 *
 * Supports chaining additional guards and then declaring the guarded
 * transition.
 */
export interface FsmGuardedTransitionBuilder<State extends string, Events extends EventMap, Context, K extends EventName<Events>> extends FsmTransitionBuilder<State, Events, Context, K> {
  /**
   * Adds another guard to the current guarded transition.
   *
   * Guards are evaluated in declaration order. All guards in the chain must
   * pass for the transition to be selected.
   */
  when(cond: FsmGuard<State, Events, K, Context>): this 
}

/**
 * Builder used to declare actions for a transition.
 */
export interface FsmTransitionActionsBuilder<State extends string, Events extends EventMap, Context, K extends EventName<Events>> {
  /**
   * Adds a transition action.
   *
   * Transition actions run when the transition fires. Multiple transition
   * actions are allowed and run in declaration order.
   *
   * See {@link FsmTransitionAction} for the action function type
   * signature.
   */
  action(action: FsmTransitionAction<State, Events, K, Context>): void 
}
