//                          Action type definitions                         //
//----------------------------------------------------------------------------//

import type { EventMap, EventName, PayloadOf } from './event-types'
import type { FsmActionApi } from './fsm-action-api'

export type TransitionKind = 'external' | 'internal'

//
// -------------- Guards ----------------
//

type GuardParams<
  State extends string,
  Events extends EventMap,
  Context,
  E extends EventName<Events>
> =
  {
    [V in E]: {
      event: V
      payload: Readonly<PayloadOf<Events, V>>
      context: Readonly<Context>
      meta: Readonly<{
        state: State
        transitionKind: TransitionKind
      }>
    }
  }[E]


export type Guard<State extends string, Events extends EventMap, Context, E extends EventName<Events>> =
  (params: GuardParams<State, Events, Context, E>) => boolean


//
// -------------- Meta ----------------
//

export type BeginMeta<State extends string> = {
  state: State
}

export type TransitionMeta<State extends string> = {
  fromState: State
  toState:   State
  transitionKind: TransitionKind
}

export type EntryMeta<State extends string, Events extends EventMap, E extends EventName<Events>> = {
  cause:     'transition'
  fromState: State
  event:     E
  payload:   Readonly<PayloadOf<Events, E>>
} | {
  cause:     'initial'
  fromState: undefined
  event:     undefined
  payload:   undefined
}

export type ExitMeta<State extends string, Events extends EventMap, E extends EventName<Events>> = {
  toState:        State
  event:          E
  payload: Readonly<PayloadOf<Events, E>>
}

export type EventActionMeta<State extends string>                                                       = BeginMeta<State> | TransitionMeta<State>
export type StateActionMeta<State extends string, Events extends EventMap, E extends EventName<Events>> = EntryMeta<State, Events, E> | ExitMeta<State, Events, E>
export type ActionMeta<State extends string, Events extends EventMap, E extends EventName<Events>>      = EventActionMeta<State> | StateActionMeta<State, Events, E>

//
// -------------- Params ----------------
//


export type EventActionParams<
  State extends string,
  Events extends EventMap,
  Context,
  E extends EventName<Events>,
  Meta extends EventActionMeta<State>
> =
  {
    [V in E]: {
      event: V
      payload: Readonly<PayloadOf<Events, V>>
      context: Context
      meta: Readonly<Meta>
      fsm: FsmActionApi<Events>
    }
  }[E]

export type StateActionParams<
  State extends string,
  Events extends EventMap,
  Context,
  E extends EventName<Events>,
  Meta extends StateActionMeta<State, Events, E>
> = {
  state:   State
  context: Context
  fsm:     FsmActionApi<Events>
  meta:    Readonly<Meta>
}

export type ActionParams<
  State extends string,
  Events extends EventMap,
  Context,
  E extends EventName<Events>,
  Meta extends ActionMeta<State, Events, E>
> = Meta extends EventActionMeta<State>            ? EventActionParams<State, Events, Context, E, Meta> :
    Meta extends StateActionMeta<State, Events, E> ? StateActionParams<State, Events, Context, E, Meta> :
    never

//
// -------------- Action types ----------------

export type Action<
  State extends string,
  Events extends EventMap,
  Context,
  E extends EventName<Events>,
  Meta extends ActionMeta<State, Events, E> = ActionMeta<State, Events, E>
> =
  (params: ActionParams<State, Events, Context, E, Meta>) => void

export type EventAction<
  State extends string,
  Events extends EventMap,
  Context,
  E extends EventName<Events>,
  Meta extends EventActionMeta<State> = EventActionMeta<State>
> = Action<State, Events, Context, E, Meta>

export type BeginAction<State extends string, Events extends EventMap, Context, E extends EventName<Events> = EventName<Events>>      = EventAction<State, Events, Context, E, BeginMeta<State>>
export type TransitionAction<State extends string, Events extends EventMap, Context, E extends EventName<Events> = EventName<Events>> = EventAction<State, Events, Context, E, TransitionMeta<State>>


export type StateAction<
  State extends string,
  Events extends EventMap,
  Context,
  E extends EventName<Events> = EventName<Events>,
  Meta extends StateActionMeta<State, Events, E> = StateActionMeta<State, Events, E>
> = Action<State, Events, Context, E, Meta>

export type EntryAction<State extends string, Events extends EventMap, Context, E extends EventName<Events> = EventName<Events>> = StateAction<State, Events, Context, E, EntryMeta<State, Events, E>>
export type ExitAction<State extends string, Events extends EventMap, Context, E extends EventName<Events> = EventName<Events>>  = StateAction<State, Events, Context, E, ExitMeta<State, Events, E>>
